"use client";

import { useState } from "react";
import { Preview } from "./preview-generation";
import { ErrorGeneration } from "./error-generation";
import { FormGeneration } from "./form-generation";
import { HeaderGeneration } from "./header-generation";

interface CardSettings {
  style: string;
  backgroundColor: string;
  lighting: string;
  pose: string;
  aspectRatio: string;
}

export default function AICardGeneration() {
  const [showForm, setShowForm] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [settings, setSettings] = useState<CardSettings>({
    style: "artistic",
    backgroundColor: "studio",
    lighting: "studio",
    pose: "profile",
    aspectRatio: "4:5",
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setShowForm(false);
    setIsLoading(true);
    setError(null);

    try {
      await new Promise((resolve) => setTimeout(resolve, 3000));
      setShowForm(false);
    } catch (err) {
      setError("Failed to generate video. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleBackToSettings = () => {
    setShowForm(true);
    setError(null);
  };

  return (
    <div className="group relative overflow-hidden w-full max-w-sm bg-white dark:bg-zinc-900 border border-zinc-200 dark:border-zinc-800 rounded-2xl transition-all duration-300 hover:shadow-[0_8px_30px_rgb(0,0,0,0.12)] dark:hover:shadow-[0_8px_30px_rgb(0,0,0,0.2)] min-h-[500px] flex flex-col justify-between gap-2">
      <HeaderGeneration />
      <div className="flex-1 overflow-hidden flex flex-col">
        {error && <ErrorGeneration error={error} />}

        {showForm ? (
          <FormGeneration
            onSubmit={handleSubmit}
            settings={settings}
            onSettingsChange={setSettings}
          />
        ) : (
          <div className="p-4">
            <Preview
              isLoading={isLoading}
              imageUrl="https://ferf1mheo22r9ira.public.blob.vercel-storage.com/profile-mjss82WnWBRO86MHHGxvJ2TVZuyrDv.jpeg"
            />

            {!isLoading && (
              <div className="space-y-4">
                <div className="p-3 space-y-2 bg-zinc-50 dark:bg-zinc-800/50 rounded-xl">
                  <div className="flex justify-between text-sm">
                    <span className="text-zinc-500">Quality</span>
                    <span className="text-zinc-900 dark:text-zinc-100">1080p</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-zinc-500">Duration</span>
                    <span className="text-zinc-900 dark:text-zinc-100">00:07</span>
                  </div>
                </div>

                <div className="flex items-center justify-between gap-2">
                  <button
                    type="button"
                    onClick={handleBackToSettings}
                    className="w-full h-9 flex items-center justify-center gap-2 border border-zinc-200 dark:border-zinc-700 text-zinc-900 dark:text-zinc-100 text-sm font-medium rounded-xl hover:bg-zinc-50 dark:hover:bg-zinc-800 transition-colors"
                  >
                    Back to Settings
                  </button>
                  <button
                    type="button"
                    className="w-full h-9 flex items-center justify-center gap-2 bg-zinc-900 hover:bg-zinc-800 dark:bg-white dark:hover:bg-zinc-100 dark:text-zinc-900 text-white text-sm font-medium rounded-xl transition-colors"
                  >
                    Download
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

export function ErrorGeneration({ error }: { error: string }) {
  return (
    <div className="mx-4 mt-2 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-800 dark:border-red-900/60 dark:bg-red-950/40 dark:text-red-200">
      {error}
    </div>
  );
}

"use client";

interface CardSettings {
  style: string;
  backgroundColor: string;
  lighting: string;
  pose: string;
  aspectRatio: string;
}

const fieldClass =
  "mt-1 w-full rounded-lg border border-zinc-200 bg-white px-3 py-2 text-sm text-zinc-900 outline-none focus:border-zinc-400 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100 dark:focus:border-zinc-500";

export function FormGeneration({
  onSubmit,
  settings,
  onSettingsChange,
}: {
  onSubmit: (e: React.FormEvent) => void;
  settings: CardSettings;
  onSettingsChange: (next: CardSettings) => void;
}) {
  const update = <K extends keyof CardSettings>(key: K, value: CardSettings[K]) => {
    onSettingsChange({ ...settings, [key]: value });
  };

  return (
    <form onSubmit={onSubmit} className="flex flex-1 flex-col gap-4 p-4">
      <div className="grid gap-3">
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Style
          <select
            className={fieldClass}
            value={settings.style}
            onChange={(e) => update("style", e.target.value)}
          >
            <option value="artistic">Artistic</option>
            <option value="realistic">Realistic</option>
            <option value="minimal">Minimal</option>
          </select>
        </label>
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Background
          <select
            className={fieldClass}
            value={settings.backgroundColor}
            onChange={(e) => update("backgroundColor", e.target.value)}
          >
            <option value="studio">Studio</option>
            <option value="outdoor">Outdoor</option>
            <option value="abstract">Abstract</option>
          </select>
        </label>
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Lighting
          <select
            className={fieldClass}
            value={settings.lighting}
            onChange={(e) => update("lighting", e.target.value)}
          >
            <option value="studio">Studio</option>
            <option value="soft">Soft</option>
            <option value="dramatic">Dramatic</option>
          </select>
        </label>
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Pose
          <select
            className={fieldClass}
            value={settings.pose}
            onChange={(e) => update("pose", e.target.value)}
          >
            <option value="profile">Profile</option>
            <option value="front">Front</option>
            <option value="three-quarter">Three-quarter</option>
          </select>
        </label>
        <label className="text-xs font-medium text-zinc-600 dark:text-zinc-400">
          Aspect ratio
          <select
            className={fieldClass}
            value={settings.aspectRatio}
            onChange={(e) => update("aspectRatio", e.target.value)}
          >
            <option value="4:5">4:5</option>
            <option value="1:1">1:1</option>
            <option value="16:9">16:9</option>
          </select>
        </label>
      </div>
      <button
        type="submit"
        className="mt-auto h-10 rounded-xl bg-zinc-900 text-sm font-medium text-white transition-colors hover:bg-zinc-800 dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-100"
      >
        Generate
      </button>
    </form>
  );
}

"use client";

export function HeaderGeneration() {
  return (
    <div className="px-4 pt-4 pb-2 border-b border-zinc-100 dark:border-zinc-800">
      <p className="text-xs font-medium uppercase tracking-wide text-zinc-500">AI card</p>
      <h3 className="mt-1 text-lg font-semibold text-zinc-900 dark:text-zinc-50">
        Generation preview
      </h3>
    </div>
  );
}

"use client";

import Image from "next/image";

export function Preview({ isLoading, imageUrl }: { isLoading: boolean; imageUrl: string }) {
  if (isLoading) {
    return (
      <div className="flex aspect-[4/5] w-full items-center justify-center rounded-xl bg-zinc-100 dark:bg-zinc-800">
        <div className="h-8 w-8 animate-spin rounded-full border-2 border-zinc-300 border-t-zinc-600 dark:border-zinc-600 dark:border-t-zinc-200" />
      </div>
    );
  }

  return (
    <div className="relative aspect-[4/5] w-full overflow-hidden rounded-xl bg-zinc-100 dark:bg-zinc-800">
      <Image
        src={imageUrl}
        alt="Generated preview"
        fill
        className="object-cover"
        sizes="(max-width: 24rem) 100vw, 24rem"
      />
    </div>
  );
}
